def check(output, ctx):
    try:
        p = parse_json(output)
        if not isinstance(p, dict):
            return True
        text = ctx['text']
        if '  ' in text or any(c in text for c in '\t\n\r'):
            return True
        toks = text.lower().split(' ')
        spans = set()
        n = len(toks)
        for i in range(n):
            for j in range(i + 1, min(n, i + 40) + 1):
                spans.add(' '.join(toks[i:j]))
        for v in p.values():
            if not isinstance(v, list):
                continue
            for e in v:
                if not isinstance(e, str):
                    continue
                s = e.lower().strip()
                if len(s.split(' ')) > 40:
                    continue
                if s not in spans:
                    return False
        return True
    except Exception:
        return True

