def check(output, ctx):
    try:
        p = parse_json(output)
        if not isinstance(p, dict):
            return True
        toks = ctx['text'].lower().split()
        from collections import Counter
        c = Counter()
        for v in p.values():
            if isinstance(v, list):
                for e in v:
                    if isinstance(e, str):
                        c[e.lower().strip()] += 1
        for s, k in c.items():
            st = s.split()
            m = len(st)
            if m == 0:
                continue
            occ = sum(1 for i in range(len(toks) - m + 1) if toks[i:i + m] == st)
            if occ == 0:
                continue
            if k > occ:
                return False
        return True
    except Exception:
        return True

