def check(output, ctx):
    try:
        p = parse_json(output)
        if not isinstance(p, dict):
            return True
        toks = ctx['text'].lower().split()
        items = []
        for v in p.values():
            if isinstance(v, list):
                for e in v:
                    if isinstance(e, str):
                        items.append(e.lower().strip().split())
        cands = []
        for st in items:
            m = len(st)
            if m == 0:
                return True
            c = [i for i in range(len(toks) - m + 1) if toks[i:i + m] == st]
            if not c:
                return True
            cands.append((m, c))
        cands.sort(key=lambda x: len(x[1]))
        used = [False] * len(toks)
        steps = [0]

        def bt(k):
            steps[0] += 1
            if steps[0] > 20000:
                raise RuntimeError
            if k == len(cands):
                return True
            m, c = cands[k]
            for i in c:
                if not any(used[i:i + m]):
                    for j in range(i, i + m):
                        used[j] = True
                    if bt(k + 1):
                        return True
                    for j in range(i, i + m):
                        used[j] = False
            return False

        try:
            return bt(0)
        except RuntimeError:
            return True
    except Exception:
        return True

