def check(output, ctx):
    try:
        p = parse_json(output)
        if not isinstance(p, dict):
            return True
        toks = ctx['text'].lower().split()
        pairs = set(zip(toks, toks[1:]))
        ts = set(toks)
        for v in p.values():
            if isinstance(v, list):
                for e in v:
                    if isinstance(e, str):
                        w = e.lower().split()
                        if not all(x in ts for x in w):
                            continue
                        for a, b in zip(w, w[1:]):
                            if (a, b) not in pairs:
                                return False
        return True
    except Exception:
        return True
